mapper.select:
SELECT ur.user_report_id AS userReportId, ur.reporter_user_id AS reporterUserId, ur.reported_user_id AS reportedUserId, ur.report_reason_cd AS reportReasonCd, ur.report_comment AS reportComment, ur.processing_status_cd AS processingStatusCd, ur.created_date AS createdDate, ur.processed_date AS processedDate, ur.processor_id AS processorId, reporter.user_nickname AS reporterNickname, reported.user_nickname AS reportedNickname FROM tb_user_report ur JOIN tb_user reporter ON ur.reporter_user_id = reporter.user_id JOIN tb_user reported ON ur.reported_user_id = reported.user_id WHERE 1=1
AND (reporter.user_nickname LIKE '%' || #{keyword} || '%' OR reported.user_nickname LIKE '%' || #{keyword} || '%')
AND ur.report_reason_cd = #{reportReasonCd}
AND ur.processing_status_cd = #{statusCd}
AND ur.user_report_id < #{lastUserReportId}
ORDER BY ur.user_report_id DESC
FETCH FIRST #{limit} ROWS ONLY

mapper.update:
UPDATE tb_user_report
SET processing_status_cd = #{statusCd},
processor_id         = #{processorId},
processed_date       = #{processedDate}
WHERE user_report_id       = #{userReportId}
